<?php
use Illuminate\Support\Facades\Route;
use App\Http\Controllers\Api\V1\{AuthController,BusinessController};
use App\Http\Middleware\MobileSession;
Route::prefix('v1')->name('mobile.')->group(function(){
    Route::post('auth/login',[AuthController::class,'login'])->middleware('throttle:10,1');
    Route::middleware('auth:sanctum')->group(function(){
        Route::post('auth/logout',[AuthController::class,'logout'])->name('logout');
        Route::post('auth/2fa',[AuthController::class,'verify'])->middleware([MobileSession::class.':pending','throttle:10,1']);
        Route::middleware(MobileSession::class)->group(function(){
            Route::get('session',[AuthController::class,'session']);
            Route::get('devices',[AuthController::class,'devices']);
            Route::delete('devices/{id}',[AuthController::class,'revoke'])->whereNumber('id');
            Route::get('dashboard',[BusinessController::class,'dashboard']);
            Route::get('actions/lookups/{kind}',[\App\Http\Controllers\Api\V1\DetailActionController::class,'lookup']);
            Route::get('actions/{kind}/{id}/form',[\App\Http\Controllers\Api\V1\DetailActionController::class,'form'])->whereIn('kind',['customers','vehicles','invoices'])->whereNumber('id');
            Route::put('actions/{kind}/{id}',[\App\Http\Controllers\Api\V1\DetailActionController::class,'update'])->whereIn('kind',['customers','vehicles','invoices'])->whereNumber('id');
            Route::get('actions/invoices/{id}/payment-form',[\App\Http\Controllers\Api\V1\DetailActionController::class,'paymentForm'])->whereNumber('id');
            Route::post('actions/invoices/{id}/preview',[\App\Http\Controllers\Api\V1\DetailActionController::class,'preview'])->whereNumber('id');
            Route::post('actions/invoices/{id}/payments',[\App\Http\Controllers\Api\V1\DetailActionController::class,'payment'])->whereNumber('id');
            Route::get('workspace/menu',[\App\Http\Controllers\Api\V1\WorkspaceController::class,'menu']);
            Route::get('workspace/account',[\App\Http\Controllers\Api\V1\WorkspaceController::class,'account']);
            Route::match(['GET','PUT'],'workspace/business-settings',[\App\Http\Controllers\Api\V1\WorkspaceController::class,'business']);
            Route::get('workspace/reports/{report}',[\App\Http\Controllers\Api\V1\WorkspaceController::class,'report'])->whereIn('report',['usage','cash']);
            Route::get('workspace/catalog/{module}',[\App\Http\Controllers\Api\V1\WorkspaceController::class,'index']);
            Route::get('workspace/catalog/{module}/{id}',[\App\Http\Controllers\Api\V1\WorkspaceController::class,'show'])->whereNumber('id');
            Route::get('notifications',[\App\Http\Controllers\Api\V1\NotificationController::class,'index']);
            Route::put('push-device',[\App\Http\Controllers\Api\V1\PushDeviceController::class,'store']);
            Route::delete('push-device',[\App\Http\Controllers\Api\V1\PushDeviceController::class,'destroy']);
            Route::post('notifications/{id}/read',[\App\Http\Controllers\Api\V1\NotificationController::class,'read'])->whereNumber('id');
            Route::get('appointments',[\App\Http\Controllers\Api\V1\AppointmentController::class,'index']);
            Route::get('appointments/{id}',[\App\Http\Controllers\Api\V1\AppointmentController::class,'show'])->whereNumber('id');
            Route::post('appointments/{id}/status',[\App\Http\Controllers\Api\V1\AppointmentController::class,'status'])->whereNumber('id');
            Route::post('customers',[BusinessController::class,'storeCustomer']);
            Route::get('lookups/{kind}',[\App\Http\Controllers\Api\V1\VehicleRegistrationController::class,'lookup'])->whereIn('kind',['vehicle-customers','vehicle-types','vehicle-brands']);
            Route::post('vehicles',[\App\Http\Controllers\Api\V1\VehicleRegistrationController::class,'store']);
            Route::get('{kind}',[BusinessController::class,'index'])->whereIn('kind',['customers','vehicles','services']);
            Route::get('{kind}/{id}',[BusinessController::class,'show'])->whereIn('kind',['customers','vehicles','services'])->whereNumber('id');
        });
    });
});
